//! The host's view of the buffers the shaders share: sizes, offsets and record layouts.
//!
//! Every constant is generated by `build.rs` from `shaders/layout.glsl`, the one place they are
//! written, so the host cannot disagree with the shaders about a word. This module also converts
//! between a [`Program`] and the fixed-layout integer records the shaders read and write. Nothing
//! here transfers a Rust `Vec` or enum layout: a chromosome is `u32` words only.
//!
//! A slot is a header, then `OP_CAP` operation records `{kind, dst_first, dst_count, src_first,
//! src_count}`, then `EXT_CAP` extents `{start, length}`. An operation's destination extents are
//! contiguous from `dst_first` and its source extents contiguous from `src_first`. Positions and
//! lengths are 32 bits, so an image must be smaller than [`MAX_IMAGE`] bytes.

use crate::program::Kind;
use crate::program::Op;
use crate::program::Span;

#[allow(dead_code)]
mod generated {
    include!(concat!(env!("OUT_DIR"), "/gpu_layout.rs"));
}
pub use generated::*;

/// A fitness that no program has: the slot holds nothing admissible.
pub const FITNESS_INVALID: u32 = u32::MAX;

/// Why a candidate was refused, in the order of the shaders' status codes.
pub const STATUS_NAMES: [&str; S_COUNT] = [
    "ok",
    "unchanged parent",
    "invalid operation",
    "run workspace exhausted",
    "operation capacity exhausted",
    "extent capacity exhausted",
    "profile count limit",
    "length overflow",
    "target copy reads unknown bytes",
    "manifest or decode-memory limit",
    "repair not permitted",
    "replay work budget exhausted",
];

/// The device words of one operation kind, and back.
pub fn kind_word(kind: Kind) -> Option<u32> {
    return match kind {
        Kind::Replace => Some(K_REPLACE as u32),
        Kind::Zero => Some(K_ZERO as u32),
        Kind::SourceCopy => Some(K_SOURCE as u32),
        Kind::TargetCopy => Some(K_TARGET as u32),
        Kind::Frames | Kind::Sparse => None,
    };
}

fn kind_of(word: u32) -> Option<Kind> {
    return match word as usize {
        K_REPLACE => Some(Kind::Replace),
        K_ZERO => Some(Kind::Zero),
        K_SOURCE => Some(Kind::SourceCopy),
        K_TARGET => Some(Kind::TargetCopy),
        _ => None,
    };
}

/// Why a program cannot be written into a slot.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum EncodeError {
    /// An operation kind the chromosome does not carry (`Frames`, `Sparse`).
    Kind,
    /// A position or length that does not fit 32 bits.
    Range,
    /// More operations or extents than a slot holds.
    Capacity,
}

/// The used part of a slot: its header, its operation records and its extents. A slot holds room for
/// `OP_CAP` operations and `EXT_CAP` extents, but only what a program uses is ever moved between
/// the host and the device.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SlotImage {
    pub header: Vec<u32>,
    pub ops: Vec<u32>,
    pub exts: Vec<u32>,
}

impl SlotImage {
    /// A slot holding no program and marked skipped, so the evaluation passes it over.
    pub fn skipped() -> SlotImage {
        let mut header = vec![0u32; SLOT_HDR];
        header[H_FIT] = FITNESS_INVALID;
        header[H_STATUS] = S_SKIP as u32;
        return SlotImage {
            header: header,
            ops: Vec::new(),
            exts: Vec::new(),
        };
    }

    /// The slot's header word `h`.
    pub fn word(&self, h: usize) -> u32 {
        return self.header[h];
    }
}

/// The slot image of `program`. The header carries only the counts, and the slot is marked
/// unevaluated.
pub fn encode_program(program: &[Op]) -> Result<SlotImage, EncodeError> {
    if program.len() > OP_CAP {
        return Err(EncodeError::Capacity);
    }
    let mut ops: Vec<u32> = Vec::with_capacity(program.len() * OPW);
    let mut exts: Vec<u32> = Vec::new();
    for op in program {
        let kind = match kind_word(op.kind) {
            None => return Err(EncodeError::Kind),
            Some(k) => k,
        };
        if exts.len() / 2 + op.dst.len() + op.src.len() > EXT_CAP {
            return Err(EncodeError::Capacity);
        }
        let dst_first = (exts.len() / 2) as u32;
        for s in &op.dst {
            put_extent(&mut exts, s)?;
        }
        let src_first = (exts.len() / 2) as u32;
        for s in &op.src {
            put_extent(&mut exts, s)?;
        }
        ops.extend_from_slice(&[
            kind,
            dst_first,
            op.dst.len() as u32,
            src_first,
            op.src.len() as u32,
        ]);
    }
    let mut header = vec![0u32; SLOT_HDR];
    header[H_NOPS] = program.len() as u32;
    header[H_NEXT] = (exts.len() / 2) as u32;
    header[H_FIT] = FITNESS_INVALID;
    header[H_STATUS] = S_OK as u32;
    return Ok(SlotImage {
        header: header,
        ops: ops,
        exts: exts,
    });
}

fn put_extent(exts: &mut Vec<u32>, span: &Span) -> Result<(), EncodeError> {
    if span.start > u32::MAX as u64 || span.len > u32::MAX as u64 {
        return Err(EncodeError::Range);
    }
    exts.push(span.start as u32);
    exts.push(span.len as u32);
    return Ok(());
}

/// The program held by a slot image, or `None` when it is not a well-formed program: counts or
/// extent ranges outside the slot, or a kind the host does not know.
pub fn decode_program(image: &SlotImage) -> Option<Vec<Op>> {
    let nops = image.header[H_NOPS] as usize;
    let next = image.header[H_NEXT] as usize;
    if nops > OP_CAP
        || next > EXT_CAP
        || image.ops.len() < nops * OPW
        || image.exts.len() < next * 2
    {
        return None;
    }
    let span = |index: usize| Span {
        start: image.exts[index * 2] as u64,
        len: image.exts[index * 2 + 1] as u64,
    };
    let mut out: Vec<Op> = Vec::with_capacity(nops);
    for i in 0..nops {
        let record = &image.ops[i * OPW..(i + 1) * OPW];
        let kind = kind_of(record[0])?;
        let (df, dn) = (record[1] as usize, record[2] as usize);
        let (sf, sn) = (record[3] as usize, record[4] as usize);
        if df.checked_add(dn)? > next || sf.checked_add(sn)? > next {
            return None;
        }
        out.push(Op {
            kind: kind,
            dst: (df..df + dn).map(span).collect(),
            src: (sf..sf + sn).map(span).collect(),
            level: None,
        });
    }
    return Some(out);
}

/// Cumulative, saturating counts for one mutation ID. Updated only when selection runs.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct MoveCounters {
    /// Children for which this mutation was attempted, including skipped and refused children.
    pub proposed: u32,
    /// Attempts with no valid form, marked `S_SKIP` by breeding.
    pub skipped: u32,
    /// Attempts accepted by evaluation, whether or not selected into the population.
    pub admitted: u32,
    /// Generations where this mutation produced the selected, strictly improved global best.
    pub new_best: u32,
}

/// The control words the shaders keep, read back between batches.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Counters {
    /// Generations whose selection has run, the seeding generation included.
    pub generations: u32,
    /// The best raw payload size so far, or `FITNESS_INVALID` before any candidate is admitted.
    pub best: u32,
    /// Members of the population.
    pub members: u32,
    /// Candidates evaluated.
    pub evaluated: u32,
    /// Finalists in the archive.
    pub archived: u32,
    /// Children bred.
    pub bred: u32,
    /// Children that were an unchanged parent and were not evaluated.
    pub skipped: u32,
    /// Candidates refused, by status code.
    pub refused: [u32; S_COUNT],
    /// Mutation counters indexed by the zero-based `MV_*` ID. Seeds, immigrants and crossovers
    /// are excluded. Counters saturate at `u32::MAX` and are reset by `prepare` or `load_population`.
    pub moves: [MoveCounters; MV_COUNT],
}

impl Counters {
    /// Read the counters from the control region's words.
    pub fn from_words(words: &[u32]) -> Counters {
        let mut refused = [0u32; S_COUNT];
        for (k, slot) in refused.iter_mut().enumerate() {
            *slot = words[C_REJ + k];
        }
        let moves = std::array::from_fn(|id| {
            let at = C_MOVE + id * MOVE_STATS;
            MoveCounters {
                proposed: words[at + MS_PROPOSED],
                skipped: words[at + MS_SKIPPED],
                admitted: words[at + MS_ADMITTED],
                new_best: words[at + MS_NEW_BEST],
            }
        });
        return Counters {
            moves: moves,
            generations: words[C_GEN],
            best: words[C_BEST],
            members: words[C_NVALID],
            evaluated: words[C_EVALS],
            archived: words[C_ARCHIVED],
            bred: words[C_BRED],
            skipped: words[C_SKIPPED],
            refused: refused,
        };
    }

    /// Candidates refused for `reason`, a status code.
    pub fn refused_for(&self, reason: usize) -> u32 {
        return self.refused[reason];
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn s(start: u64, len: u64) -> Span {
        return Span {
            start: start,
            len: len,
        };
    }

    #[test]
    fn a_program_survives_a_round_trip_through_a_slot() {
        let program = vec![
            Op::new(Kind::Replace, vec![s(10, 5), s(0, 3)]),
            Op::copy(Kind::SourceCopy, vec![s(20, 4), s(40, 2)], vec![s(7, 6)]),
            Op::new(Kind::Zero, vec![s(90, 1)]),
            Op::copy(Kind::TargetCopy, vec![s(60, 8)], vec![s(0, 4), s(30, 4)]),
        ];
        let image = encode_program(&program).unwrap_or_else(|e| panic!("{:?}", e));
        assert_eq!(image.header.len(), SLOT_HDR);
        assert_eq!(image.ops.len(), program.len() * OPW);
        assert_eq!(decode_program(&image), Some(program));
    }

    #[test]
    fn encodings_the_chromosome_does_not_carry_and_oversize_values_are_refused() {
        assert_eq!(
            encode_program(&[Op::new(Kind::Sparse, vec![s(0, 1)])]),
            Err(EncodeError::Kind)
        );
        assert_eq!(
            encode_program(&[Op::new(Kind::Replace, vec![s(u32::MAX as u64 + 1, 1)])]),
            Err(EncodeError::Range)
        );
        let many = vec![Op::new(Kind::Zero, vec![s(0, 1)]); OP_CAP + 1];
        assert_eq!(encode_program(&many), Err(EncodeError::Capacity));
        let wide = vec![Op::new(Kind::Replace, vec![s(0, 1); EXT_CAP + 1])];
        assert_eq!(encode_program(&wide), Err(EncodeError::Capacity));
    }

    #[test]
    fn move_counters_decode_in_mutation_id_order() {
        let mut words = vec![0; CTL_WORDS];
        for id in 0..MV_COUNT {
            for stat in 0..MOVE_STATS {
                words[C_MOVE + id * MOVE_STATS + stat] = (id * MOVE_STATS + stat + 1) as u32;
            }
        }
        let counters = Counters::from_words(&words);
        for id in 0..MV_COUNT {
            assert_eq!(
                counters.moves[id],
                MoveCounters {
                    proposed: (id * MOVE_STATS + MS_PROPOSED + 1) as u32,
                    skipped: (id * MOVE_STATS + MS_SKIPPED + 1) as u32,
                    admitted: (id * MOVE_STATS + MS_ADMITTED + 1) as u32,
                    new_best: (id * MOVE_STATS + MS_NEW_BEST + 1) as u32,
                }
            );
        }
    }

    #[test]
    fn the_layout_matches_the_shader_header() {
        assert_eq!(SLOT_WORDS, SLOT_HDR + OP_CAP * OPW + EXT_CAP * 2);
        assert_eq!(STATE_WORDS, ST_SLOTS + SLOTS * SLOT_WORDS);
        assert!(DEFAULT_ELITES <= POP);
        assert_eq!(NCAND, std::cmp::max(CHILDREN, POP));
        assert_eq!(POOL, POP + NCAND);
        assert!(C_REJ + S_COUNT <= C_MOVE);
        assert!(C_MOVE + MV_COUNT * MOVE_STATS <= CTL_WORDS);
        assert!(H_MOVE < SLOT_HDR);
        assert!(MAX_IMAGE <= u32::MAX as usize);
    }
}
